// Regression test: a variable assigned in EVERY arm of a provably-
// exhaustive `compare` (enum subject covering all variants, or an
// explicit `otherwise`) must be considered definitely assigned afterward
// -- not flagged as "used before it has a value".
//
// Root cause: CFGBuilder::visitCompare() unconditionally added a "nothing
// matched" fallthrough edge straight from the compare's entry block to its
// merge block, even when the compare was provably exhaustive. That edge
// doesn't affect reachability (nothing reads it for that purpose), but
// DefiniteAssignmentPass's dataflow computes "is X assigned here" as the
// INTERSECTION of "assigned at end" across every predecessor of a block --
// and the spurious fallthrough edge is a predecessor where NOTHING is
// assigned (no arm ran), dragging the intersection down to "unassigned"
// even when every real arm assigns the same variable. Fixed by only adding
// that edge when the compare is NOT provably exhaustive.

import io;

import test;
enum Color { Red, Green, Blue }

fn main(): int {
    // Case 1: exhaustive enum compare (SubjectIsEnum, no explicit otherwise).
    mut c: Color = Color::Green;
    mut y: int;
    compare c {
        matches Color::Red:
        y = 1;
        done
        matches Color::Green:
        y = 2;
        done
        matches Color::Blue:
        y = 3;
        done
    }
    test::assert(y == 2, "");

    // Case 2: int compare with an explicit `otherwise` (exhaustive via
    // otherwise, not via SubjectIsEnum).
    mut x: int = 5;
    mut z: int;
    match x {
        matches 1:
        z = 10;
        done
        matches 2:
        z = 20;
        done
        otherwise:
        z = 99;
    }
    test::assert(z == 99, "");

    io::printline("ok");
    return 0;
}

// Regression test: a function whose ENTIRE body is a single, provably-
// exhaustive `compare` (every enum variant covered, return in every arm)
// with NO trailing statement after the compare must compile and run
// cleanly -- must NOT trigger a false "The function ... promises to give
// back a result, but sometimes it doesn't!" error.
//
// This used to be a tracked, accepted limitation (previously
// tests/10_known_bugs/fail_compare_only_body_missing_return.tr, later
// tests/99_known_bugs/... after a folder renumbering) -- CFG::allPathsReturn()
// only counts a predecessor of the virtual exit block against a function
// if that predecessor is actually reachable (`Pred->isReachable()`), and
// when every arm of an exhaustive compare returns, the compare's merge
// block ends up with zero incoming edges (see src/analysis/CFG.cpp's visitCompare()
// doc comment) -- genuinely unreachable, and therefore correctly excluded
// from the check. Re-verified live while auditing 99_known_bugs/ and found
// to already compile and run correctly; moved here as a real passing test
// instead of a documented limitation.
//
// Companion to 20_compare_param_subject_exhaustive.tr, which covers the
// same shape WITH a trailing "belt and suspenders" return -- this file is
// the same function with that trailing line removed entirely.
import test;

enum Direction { North, East, South, West }

fn describe(d: Direction): int {
    compare d {
        matches Direction::North:
        return 1;
        break;
        matches Direction::East:
        return 2;
        done
        matches Direction::South:
        return 3;
        done
        matches Direction::West:
        return 4;
        done
    }
}

fn main(): int {
    test::assert(describe(Direction::North) == 1, "");
    test::assert(describe(Direction::East) == 2, "");
    test::assert(describe(Direction::South) == 3, "");
    test::assert(describe(Direction::West) == 4, "");
    return 0;
}

