// This exercises the worklist's fixed-point loop specifically
// (Monomorphize.h/.cpp, drainFreeFunctionRequests()): re-typechecking
// `outer`'s freshly-substituted clone is what DISCOVERS `inner<int>`'s
// request in the first place (it does not exist before `outer<int>` is
// itself being processed), so this only compiles correctly if a request
// recorded DURING draining is picked up by the SAME drain loop rather than
// requiring a second pass. Also the regression test for a real bug caught
// live during this session: a `std::vector`-backed instantiation cache
// dangled the `InstantiationEntry&` this exact nested-discovery pattern
// holds across record() calls -- see the change record's *Removed
// assumptions* for the fix (a `std::deque` instead).

import test;

fn<T> inner(x: T): T {
    return x;
}

fn<T> outer(x: T): T {
    return inner(x);
}

fn main(): int {
    a := outer(7);
    immut b: string = outer("hello");
    test::assert(a == 7, "nested generic (int) failed");
    test::assert(b == "hello", "nested generic (string) failed");
    return 0;
}

// Regression test: TYPE-002 S14a -- completion criterion 4's struct-field
// half. `02_sizeof_t_in_generic_body.tr` (S12a) already covers `sizeof(T)`
// inside a generic FREE function; this covers the same mechanism inside a
// generic STRUCT's own method, including a >8-byte T (Big, 24 bytes) --
// which only became possible to even ASK correctly once S13a/S13b gave
// each instantiation its own real per-instantiation struct layout instead
// of Type Erasure's uniform "every T is 8 bytes" assumption.
#include <test>

struct Big {
    a: int,
    b: int,
    c: int
}

struct Box<T> {
    val: T
}

fn<T> Box.sizeOfT(): int {
    return sizeof(T);
}

fn main(): int {
    mut bi: Box<int> = Box.default();
    mut bd: Box<double> = Box::default();
    mut bbig: Box<Big> = Box::default();
    test::assert(bi.sizeOfT() == 8, "sizeof(T) in Box<int>.sizeOfT() wrong");
    test::assert(bd.sizeOfT() == 8, "sizeof(T) in Box<double>.sizeOfT() wrong");
    test::assert(bbig.sizeOfT() == 24, "sizeof(T) in Box<Big>.sizeOfT() wrong");
    return 0;
}

