    }
    return 0;
}

fn overwritten(): H {
    mut n: N = N::default();
    mut h: H = H::default();
    h.head = &n;
    h.head = heap(N::default());
    return h;
}

fn overwritten_whole(): H {
    mut n: N = N::default();
    mut h: H = H::default();
    h.head = &n;
    h = H::default();
    return h;
}

fn local_array(): int {
    mut n: N = N::default();
    n.val = 4;
    mut a: (&N)[2] = [&n, &n];
    mut t: int = 0;
    for x in a {
