    }
    return 0;
}

fn repointed_first(h: H2): int {
    mut n: N = N::default();
    mut m: N = N::default();
    h.own = &m;
    h.own.next = &n;
    return 7;
}

fn through_call(p: &N): &N {
    return id(p);
}

fn heap_through_call(): &N {
    return id(heap(N::default()));
}

fn list_of_heap(): int {
    mut n: N = N::default();
    n.val = 8;
    mut h: H = H::default();
    h.head = heap(n);
    mut l: List<H> = List::default();
    l.push(h);
    return l.length();
}

