// NM-2 (issue #348): the shapes the value ranges prove safe, so their
// overflow or bounds checks are removed, still compute the right values: a
// counter bounded by its loop condition, a range `for` indexing a fixed-size
// array, values reduced by `%`, `&` and `>>`, a value bounded by an earlier
// guard, and a counting-down `for`. If a range were wrong, a value here would
// come out different.
import test;

fn count_to(n: int): int {
    mut i: int = 0;
    mut s: int = 0;
    while i < n {
        s = s + i % 10;
        i += 1;
    }
    return s;
}

fn total(a: int[16]): int {
    mut t: int = 0;
    for i in 0..16 {
        t = t + a[i];
    }
    return t;
}

fn reduced(x: int, a: int[16]): int {
    return a[x & 15] + (x % 7) * 3 + (x >> 60);
}

fn guarded(n: int): int {
    if n < 0 || n > 1000 {
        return -1;
    }
    return n * n + 1;
}

fn countdown(a: int[8]): int {
    mut s: int = 0;
    for i in 7..-1 step i-- {
        s = s * 2 + a[i];
    }
    return s;
}

fn main(): int {
    mut a: int[16];
    for i in 0..16 {
        a[i] = i * 3;
    }
    mut b: int[8] = {1, 0, 1, 1, 0, 0, 1, 0};
    test::assert(count_to(25) == 100, "loop counter");
    test::assert(total(a) == 360, "range for over an array");
    test::assert(reduced(37, a) == 15 + 6, "`&`, `%`, `>>`");
    test::assert(reduced(9223372036854775807, a) == 45 + 0 + 7, "`&`, `%`, `>>` at the limit");
    test::assert(guarded(30) == 901, "guarded product");
    test::assert(guarded(5000) == -1, "guard");
    test::assert(countdown(b) == 77, "counting down");
    return 0;
}

// The compile-time bounds check (E001) uses the same dataflow as check
// elision, and rejected these valid programs: it read `i` as 5 after three
// `i--` statements and after a `defer` that set it to 0, because neither
// write was modelled. A variable written in a way the dataflow does not
// follow now has no constant, so neither access is judged at compile time.
import test;

fn after_postfix(): int {
    mut a: int[3] = [1, 2, 3];
    mut i: int = 5;
    i--;
    i--;
    i--;
    return a[i];
}

fn after_defer(): int {
    mut a: int[3] = [1, 2, 3];
    mut i: int = 5;
    if True {
        defer i = 0;
    }
    return a[i];
}

fn main(): int {
    test::assert(after_postfix() == 3, "a[2] after three i--");
    test::assert(after_defer() == 1, "a[0] after the defer ran");
    return 0;
}

// LEC-003: struct destructuring -- a literal field test, a bound field, `..`,
// and a guard, tried in source order (first match wins).
import test;

struct Point { x: int, y: int }

fn classify(p: Point): int {
    mut r: int;
    compare p {
        matches Point { x: 0, y: 0 }:
        r = 1;
        done
        case Point { x, y } if x == y:
        r = 2;
        done
        matches Point { x: 0, .. }:
        r = 3;
        done
        matches Point { x, y }:
        r = x + y;
        done
    }
    return r;
}

fn main(): int {
    mut a: Point = Point::default();
    test::assert(classify(a) == 1, "origin matches the first arm");
    a.x = 3;
    a.y = 3;
    test::assert(classify(a) == 2, "x == y hits the guarded arm");
    a.x = 0;
    a.y = 7;
    test::assert(classify(a) == 3, "x == 0 with y ignored");
    a.x = 4;
    a.y = 5;
    test::assert(classify(a) == 9, "bindings are the field values");
    return 0;
}

// LEC-003: a binding shadows an outer name for its arm only, including a
// `for` loop variable.
import test;

struct Point { x: int, y: int }

fn main(): int {
    mut x: int = 100;
    mut p: Point = Point::default();
    p.x = 5;
    p.y = 6;
    switch (p) {
        matches Point { x, y }:
        test::assert(x == 5, "binding x shadows the outer x");
        test::assert(y == 6, "binding y");
        done
    }
    test::assert(x == 100, "the outer x is untouched and visible again");

    mut seen: int = 0;
    for i in 0..3 step i += 1 {
        p.x = i + 10;
        compare p {
            matches Point { x: i, .. }:
            seen = seen + i;
            done
        }
        seen = seen + i;
    }
    test::assert(seen == 10 + 11 + 12 + 0 + 1 + 2, "binding named like the loop variable");
    return 0;
}

