// LEC-003: `_` (optionally guarded) on an int subject, mixed with ordinary
// value patterns.
import test;

fn f(n: int): int {
    mut r: int;
    compare n {
        matches 1: r = 10; done
        matches 2: r = 20; done
        matches _ if n > 100: r = 99; done
        matches _: r = 0; done
    }
    return r;
}

fn name(s: string): string {
    mut r: int = 0;
    compare s {
        matches "a": r = 1; done
        matches _ if s == "b": r = 2; done
    }
    return r;
}

fn main(): int {
    test::assert(f(1) == 10, "value pattern before a wildcard");
    test::assert(f(2) == 20, "second value pattern");
    test::assert(f(500) == 99, "guarded wildcard");
    test::assert(f(7) == 0, "plain wildcard");
    test::assert(name("a") == 1, "string value");
    test::assert(name("b") == 2, "string subject, guarded wildcard");
    test::assert(name("c") == 0, "non-exhaustive string compare is still a no-op");
    return 0;
}

// LEC-003: a compare with patterns inside a loop body, with `continue` inside
// an arm; the subject slot must not grow the stack per iteration.
import test;

struct P { x: int, y: int }

fn main(): int {
    mut total: int = 0;
    for i in range(0, 5) {
        mut p: P = P::default();
        p.x = i;
        p.y = i * 2;
        compare p {
            matches P { x: 0, .. }:
            total = total + 100;
            done
            matches P { y, .. } if y > 4:
            total = total + y;
            continue;
            done
            matches P { x, .. }:
