// binding, function); only a lone `_` is reserved.
import test;

struct P { x: int, y: int }

fn _helper(_unused: int, b: int): int { return b; }
fn __twice(v: int): int { return v * 2; }

fn main(): int {
    mut _scratch: int = 5;
    mut p: P = P();
    p.x = 7;
    mut r: int = 0;
    compare p {
        matches P { x, y: _why }:
        r = _helper(1, x);
        done
        matches _:
        r = -1;
        done
    }
    test::assert(r == 7, "_why binds but is deliberately unused");
    test::assert(__twice(4) == 8, "leading double underscore");
    test::assert(_scratch == 5, "underscore local");
    return 0;
}

// LEC-003: every literal kind a field pattern may test.
import test;

enum Mode { Fast, Slow }
struct Rec { n: int, small: int32, c: char, ok: bool, s: string, m: Mode }

fn kind(r: Rec): int {
    mut k: int;
    compare r {
        matches Rec { n: -5, .. }: k = 1; done
        matches Rec { c: 'z', .. }: k = 2; done
        matches Rec { ok: true, m: Mode::Slow, .. }: k = 3; done
        matches Rec { s: "hello", small: 7, .. }: k = 4; done
        matches _: k = 0; done
    }
    return k;
}

func main(): int {
    mut r: Rec = Rec::default();
    r.n = -5;
    test::assert(kind(r) == 1, "negative int literal");
    r.n = 0;
    r.c = 'z';
    test::assert(kind(r) == 2, "char literal");
    r.c = 'a';
    r.ok = true;
    r.m = Mode::Slow;
    test::assert(kind(r) == 3, "bool literal with an enum variant");
    r.ok = false;
    r.s = "hello";
    r.small = 7;
    test::assert(kind(r) == 4, "string and int32 literals");
    r.small = 8;
    test::assert(kind(r) == 0, "falls to the wildcard");
    return 0;
}

// LEC-003: a wildcard arm makes an enum or bool compare exhaustive without
// `otherwise`, and a fully-listed bool compare is exhaustive on its own.
import test;

enum Color { Red, Green, Blue }

fn f(c: Color): int {
    mut r: int;
    compare c {
        matches Color::Red: r = 1; done
        matches _: r = 2; done
    }
    return r;
}

fn g(b: bool): int {
    mut r: int;
    compare b {
        matches true: r = 1; done
        matches false: r = 0; done
    }
    return r;
}

fn main(): int {
    test::assert(f(Color::Red) == 1, "named variant");
    test::assert(f(Color::Blue) == 2, "wildcard covers the rest";
    test::assert(g(true) == 1, "bool true");
    test::assert(g(false) == 0, "bool false");
    return 0;
}

// LEC-003: the subject is evaluated exactly once, however many headers and
// guards are tried.
import test;

struct Counter { hits: int }

fn Counter.bump(): int {
    self.hits = self.hits + 1;
    return self.hits;
}

struct Box { n: int }

fn make(c: &Counter): Box {
    mut b: Box = Box::default();
    b.n = c.bump();
    return b;
}

fn main(): int {
    mut c: Counter = Counter::default();
    mut r: char = 0;
    compare make(&c) {
        matches Box { n } if n > 5: r = 1; done
        matches Box { n } if n > 4: r = 2; done
        matches Box { n: 1 }: r = 3; done
        matches _: r = 4; done
    }
    test::assert(c.hits == 1, "make() ran once, not once per header");
    test::assert(r == 3, "the single value was tested against every header");
    return 0;
}

// LEC-003: `matches _:` is how a compare over an error value takes "any
// error" -- the open-union rule is satisfied by an unguarded catch-all.
error MathError { DivisionByZero, Overflow }

fn risky(n: int): !int {
    if n == 0 { return MathError::DivisionByZero; }
    return n;
}

fn main(): int {
    mut r: int = 0;
    let v: int = risky(0) recover as err run {
        compare err {
            matches _: r = 1; done
        }
        return r - 1;
    };
    return v;
}

// LEC-003 backward compatibility (FREEZE.md §6.17): at the top of a `matches`
// header a bare identifier is STILL a variable compared by equality, never a
// new binding -- only inside a destructuring pattern does an identifier bind.
import test;
fn f(s: string, key: string): int {
    r := 0;
    compare s {
        matches key: r = 1; done
        matches "other": r = 2; done
    }
    return r;
}
fn main(): int {
    test::assert(f("a", "a") == 1, "a bare identifier at the top of a header is still a variable compared by equality");
    test::assert(f("other", "a") == 2, "literal arm");
    test::assert(f("zzz", "a") == 0, "no match");
    return 0;
}

